#include <print>
#include <vector>

std::vector<int> path;
bool used[5] = {};

void dfs() {
    if (path.size() == 4) {
        std::println("{} {} {} {}", path[0], path[1], path[2], path[3]);
        return;
    }
    for (int i = 1; i <= 4; ++i) {
        if (used[i]) continue;
        used[i] = true;
        path.push_back(i);
        dfs();
        used[i] = false;
        path.pop_back();
    }
}

int main() {
    dfs();
    return 0;
}
// 输出 24 行，第一行 1 2 3 4，最后一行 4 3 2 1

